var n=`0950-okonomiyaki`;var o=`world-0950`;var a=`JP`;var s=`east-asia`;var t=4;var g=44;var r={en:`Okonomiyaki`,ua:`Окономіякі`};var l={en:`Okonomiyaki is a Japan dish made with white cabbage, green onion, all-purpose flour, chicken egg. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Окономіякі, страва кухні країни Японія. Основні складники: білоголова капуста, зелена цибуля, пшеничне борошно універсальне, куряче яйце. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var c=[{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:10,i:[[`white-cabbage`,550,`g`],[`green-onion`,85,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:9,i:[[`all-purpose-flour`,210,`g`],[`dashi-stock`,300,`ml`],[`chicken-egg`,3,`pcs`]]},{en:`Place cabbage batter over pork slices on a hot griddle and cook the okonomiyaki slowly, flipping once without breaking.`,ua:`Викладіть капустяне тісто поверх скибочок свинини на гарячу сковороду й повільно готуйте окономіякі, один раз обережно перевернувши.`,t:[`pan-frying`],m:20,i:[[`pork-belly`,270,`g`],[`canola-oil`,45,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:5,i:[[`okonomiyaki-sauce`,115,`g`],[`mayonnaise`,90,`g`],[`aonori`,12,`g`],[`katsuobushi`,35,`g`]]}];var h={slug:n,id:o,country:`JP`,region:s,servings:4,minutes:44,title:r,text:l,steps:c};export{a as country,h as default,o as id,g as minutes,s as region,t as servings,n as slug,c as steps,l as text,r as title};